frappe.query_reports["Machine Maintenance Report"] = {
    get_formatter: function(report) {
        let formatter = report.standard_formatters;
        return function(value, row, column, data, default_formatter) {
            let formatted = default_formatter(value, row, column, data);

            // Apply colors only if not consolidated
            if (!data.consolidated) {
                if (data.status === "Overdue") {
                    formatted = `<span style="background-color: red; color: white; padding:2px 5px;">${formatted}</span>`;
                } else if (data.status === "Scheduled") {
                    formatted = `<span style="background-color: yellow; color: black; padding:2px 5px;">${formatted}</span>`;
                } else if (data.status === "Completed") {
                    formatted = `<span style="background-color: green; color: white; padding:2px 5px;">${formatted}</span>`;
                }
            }

            return formatted;
        }
    }
};
